import os, csv
from statistics import mean
import numpy as np

IN_CSV = 'storage/shared/agents/kairos/avd/avd_panels_metrics.csv'
OUT_DIR = 'storage/shared/agents/kairos/avd'
os.makedirs(OUT_DIR, exist_ok=True)

def to_float(x):
    try:
        if x is None: return None
        s = str(x).strip().lower()
        if s in ('none','nan',''): return None
        return float(x)
    except Exception:
        return None

# Load panel metrics
rows = []
with open(IN_CSV, 'r', encoding='utf-8') as f:
  reader = csv.DictReader(f)
  for r in reader:
    rows.append({
      'distribution': r['distribution'],
      'ratio': to_float(r['ratio']),
      'synergy': to_float(r['synergy']),
    })

# Group by distribution
by_dist = {}
for r in rows:
  by_dist.setdefault(r['distribution'], []).append(r)

# Ordered by ratio
for d in by_dist:
  by_dist[d] = sorted(by_dist[d], key=lambda x: x['ratio'])

# Build synergy curves per dist
dists = list(by_dist.keys())
curves = {d: [x['synergy'] for x in by_dist[d]] for d in dists}
ratios = {d: [x['ratio'] for x in by_dist[d]] for d in dists}

# Baselines
def baseline_neutral(curve): return [0.5] * len(curve)
def baseline_minmax(curve):
  vals = [v for v in curve if v is not None]
  if not vals: return [None]*len(curve)
  exp = 0.5*(min(vals)+max(vals))
  return [exp]*len(curve)
# Global historical mean
all_vals = [v for d in dists for v in curves[d] if v is not None]
hist_mean = mean(all_vals) if all_vals else None
def baseline_hist(_curve):
  return [hist_mean]*len(_curve) if hist_mean is not None else [None]*len(_curve)

# Emergence = synergy/expected - 1
def emergence(curve, exp):
  out = []
  for s, e in zip(curve, exp):
    if s is None or e is None or abs(e) < 1e-12:
      out.append(None)
    else:
      out.append(s/e - 1.0)
  return out

# Compute and write CSV
out_csv = os.path.join(OUT_DIR, 'avd_emergence_v0_3.csv')
with open(out_csv, 'w', encoding='utf-8', newline='') as f:
  writer = csv.writer(f)
  writer.writerow(['distribution','ratio','synergy','emergence_neutral','emergence_minmax','emergence_histmean'])
  for d in dists:
    bN = baseline_neutral(curves[d])
    bM = baseline_minmax(curves[d])
    bH = baseline_hist(curves[d])
    eN = emergence(curves[d], bN)
    eM = emergence(curves[d], bM)
    eH = emergence(curves[d], bH)
    for ratio, s, en, em, eh in zip(ratios[d], curves[d], eN, eM, eH):
      writer.writerow([d, ratio, s, en, em, eh])

# Summaries
def argmax(xs):
  best_i, best_v = 0, -1e9
  for i, v in enumerate(xs):
    vv = v if v is not None else float('-inf')
    if vv > best_v:
      best_v, best_i = vv, i
  return best_i, best_v

out_txt = os.path.join(OUT_DIR, 'avd_emergence_v0_3.txt')
with open(out_txt, 'w', encoding='utf-8') as f:
  f.write("AVD v0.3 — Emergence under expected baselines\n")
  f.write(f"hist_mean_synergy={hist_mean}\n")
  for d in dists:
    bN = baseline_neutral(curves[d]); eN = emergence(curves[d], bN)
    bM = baseline_minmax(curves[d]);  eM = emergence(curves[d], bM)
    bH = baseline_hist(curves[d]);    eH = emergence(curves[d], bH)
    iN, vN = argmax(eN); iM, vM = argmax(eM); iH, vH = argmax(eH)
    rN = ratios[d][iN]; rM = ratios[d][iM]; rH = ratios[d][iH]
    f.write(f"- {d}: best_r[neutral]={rN}, best_r[minmax]={rM}, best_r[histmean]={rH}; r=1.0 emergence={eN[-1]},{eM[-1]},{eH[-1]}\n")
  f.write(f"csv={out_csv}\n")

print(f"[artifacts] {out_csv} | {out_txt}")
